[[nodiscard]] inline constexpr std::optional<std::string_view> qzss_dcx_camf_a2_country_region_name_lookup(uint16_t id) noexcept {
    uint8_t lo = 0, hi = 252;
    while (lo < hi) {
        uint8_t mid = static_cast<uint8_t>(lo + (hi - lo) / 2);
        if (QZSS_DCX_CAMF_A2_COUNTRY_REGION_NAME_TABLE[mid].id == id) {
            const char* s = QZSS_DCX_CAMF_A2_COUNTRY_REGION_NAME_TABLE[mid].label;
            return s ? std::optional<std::string_view>(std::string_view{s}) : std::nullopt;
        }
        if (QZSS_DCX_CAMF_A2_COUNTRY_REGION_NAME_TABLE[mid].id < id) lo = mid + 1;
        else hi = mid;
    }
    return std::nullopt;
}
